"""Application settings.

Values come from environment variables with fixture defaults documented in
PLAN.md section 6. Everything is explicit: no hidden configuration files.
"""

from __future__ import annotations

import os
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from zoneinfo import ZoneInfo

from app.reviews.policy import PolicyConfig

# Fixture observation assumptions (PLAN.md section 6, "Observation and clock").
# These are documented assumptions, not inferred service guarantees.
DEMO_NOW_DEFAULT = datetime(2026, 7, 28, 12, 0, 0, tzinfo=timezone.utc)
COVERAGE_START_DEFAULT = datetime(2026, 2, 1, 0, 0, 0, tzinfo=timezone.utc)
COVERAGE_END_DEFAULT = datetime(2026, 7, 28, 0, 0, 0, tzinfo=timezone.utc)

DEFAULT_DATABASE_URL = "postgresql+psycopg://relay_app@127.0.0.1:5433/relay_dev"
DEFAULT_ADMIN_DATABASE_URL = "postgresql+psycopg://relay_admin@127.0.0.1:5433/relay_dev"


def _parse_utc_datetime(value: str, label: str) -> datetime:
    parsed = datetime.fromisoformat(value)
    if parsed.tzinfo is None:
        raise ValueError(f"{label} must include a UTC offset, got {value!r}")
    return parsed.astimezone(timezone.utc)


@dataclass(frozen=True)
class Settings:
    """Runtime settings for one API process."""

    database_url: str
    admin_database_url: str
    allowed_account_ids: frozenset[int] | None  # None => trusted demo admin sees all
    demo_now: datetime
    coverage_start: datetime
    coverage_end: datetime
    policy: PolicyConfig

    @classmethod
    def from_env(cls, env: dict[str, str] | None = None) -> "Settings":
        source = dict(os.environ)
        if env is not None:
            source.update(env)
        allowed_raw = (source.get("RELAY_ALLOWED_ACCOUNT_IDS") or "").strip()
        if allowed_raw:
            allowed: frozenset[int] | None = frozenset(
                int(part) for part in allowed_raw.split(",") if part.strip()
            )
        else:
            allowed = None
        return cls(
            database_url=source.get("RELAY_DATABASE_URL", DEFAULT_DATABASE_URL),
            admin_database_url=source.get(
                "RELAY_ADMIN_DATABASE_URL", DEFAULT_ADMIN_DATABASE_URL
            ),
            allowed_account_ids=allowed,
            demo_now=_parse_utc_datetime(
                source.get("RELAY_DEMO_NOW") or _iso(DEMO_NOW_DEFAULT), "RELAY_DEMO_NOW"
            ),
            coverage_start=_parse_utc_datetime(
                source.get("RELAY_COVERAGE_START") or _iso(COVERAGE_START_DEFAULT),
                "RELAY_COVERAGE_START",
            ),
            coverage_end=_parse_utc_datetime(
                source.get("RELAY_COVERAGE_END") or _iso(COVERAGE_END_DEFAULT),
                "RELAY_COVERAGE_END",
            ),
            policy=PolicyConfig(),
        )


def _iso(moment: datetime) -> str:
    return moment.isoformat()


def load_env_file(path: Path) -> None:
    """Load a .env file into os.environ without overriding existing values.

    Tiny stand-in for python-dotenv so the demo has one less dependency.
    Only KEY=VALUE lines; comments and blanks are ignored.
    """
    if not path.exists():
        return
    for line in path.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in stripped:
            continue
        key, _, value = stripped.partition("=")
        key = key.strip()
        value = value.strip().strip("'\"")
        if key and key not in os.environ:
            os.environ[key] = value


def validated_timezone(name: str) -> ZoneInfo:
    try:
        return ZoneInfo(name)
    except Exception as exc:  # invalid IANA name stored in the database
        raise ValueError(f"unknown IANA timezone {name!r}") from exc

"""Local calendar weeks, constructed with zoneinfo — never fixed 168-hour spans.

A week is Monday 00:00 local to the following Monday 00:00 local, as a
half-open interval. Each boundary is constructed as a local wall-clock
midnight and converted to an aware UTC instant, so DST transitions can make
the elapsed length 167 or 169 hours without shifting the boundaries.
"""

from __future__ import annotations

from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo

UTC = timezone.utc


class CalendarError(ValueError):
    """Malformed or unsupported calendar input."""


def parse_week_start(value: str) -> date:
    """Strictly parse YYYY-MM-DD (rejects 2026-7-2 and friends)."""
    try:
        parsed = datetime.strptime(value, "%Y-%m-%d").date()
    except ValueError as exc:
        raise CalendarError(f"week_start must be YYYY-MM-DD, got {value!r}") from exc
    if parsed.strftime("%Y-%m-%d") != value:
        raise CalendarError(f"week_start must be YYYY-MM-DD, got {value!r}")
    return parsed


def is_monday(day: date) -> bool:
    return day.weekday() == 0


def monday_of(day: date) -> date:
    return day - timedelta(days=day.weekday())


def local_midnight(monday: date, tz: ZoneInfo) -> datetime:
    """Midnight wall clock on the given date in tz, as an aware datetime."""
    return datetime(monday.year, monday.month, monday.day, tzinfo=tz)


def week_window(
    monday: date, tz: ZoneInfo
) -> tuple[datetime, datetime, datetime, datetime]:
    """(start_local, end_local, start_utc, end_utc) for the week beginning monday."""
    if not is_monday(monday):
        raise CalendarError(f"week must begin on a Monday, got {monday.isoformat()}")
    start_local = local_midnight(monday, tz)
    end_local = local_midnight(monday + timedelta(days=7), tz)
    return start_local, end_local, start_local.astimezone(UTC), end_local.astimezone(UTC)


def preceding_mondays(target: date, count: int) -> list[date]:
    """The `count` Mondays immediately before target, oldest first."""
    return [target - timedelta(weeks=k) for k in range(count, 0, -1)]


def week_covered(
    start_utc: datetime, end_utc: datetime, coverage_start: datetime, coverage_end: datetime
) -> bool:
    """A week is covered when its whole UTC interval lies inside the
    assumed recording interval."""
    return start_utc >= coverage_start and end_utc <= coverage_end


def latest_complete_monday(tz: ZoneInfo, now_utc: datetime, coverage_end: datetime) -> date:
    """Most recent Monday whose local week has fully ended by
    min(now_utc, coverage_end)."""
    limit = min(now_utc, coverage_end)
    candidate = monday_of(now_utc.astimezone(tz).date())
    for _ in range(2000):  # bounded walk; guards against unusable coverage
        _, _, _, end_utc = week_window(candidate, tz)
        if end_utc <= limit:
            return candidate
        candidate -= timedelta(days=7)
    raise CalendarError("no complete week exists within the supported coverage window")


def supported_mondays(
    tz: ZoneInfo, now_utc: datetime, coverage_start: datetime, coverage_end: datetime
) -> list[date]:
    """Every selectable complete Monday, oldest first."""
    latest = latest_complete_monday(tz, now_utc, coverage_end)
    mondays: list[date] = []
    candidate = latest
    for _ in range(2000):
        _, _, _, end_utc = week_window(candidate, tz)
        if end_utc <= coverage_start:
            break
        mondays.append(candidate)
        candidate -= timedelta(days=7)
    mondays.reverse()
    return mondays

"""Engine construction and connectivity checks."""

from __future__ import annotations

from sqlalchemy import create_engine, text
from sqlalchemy.engine import Engine


def create_db_engine(url: str, *, pool_size: int = 5, max_overflow: int = 2) -> Engine:
    return create_engine(
        url,
        pool_size=pool_size,
        max_overflow=max_overflow,
        pool_pre_ping=True,
        future=True,
    )


def ping(engine: Engine) -> bool:
    try:
        with engine.connect() as connection:
            connection.execute(text("SELECT 1"))
        return True
    except Exception:
        return False

"""HTTP error envelope: one consistent shape for every failure."""

from __future__ import annotations

from fastapi import Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse

from app.reviews.errors import ReviewError

# Domain errors that indicate caller mistakes map to 4xx; anything else in
# ReviewError is a server-side data problem (5xx).
_STATUS_BY_CODE = {
    "account_not_found": 404,
    "invalid_week": 422,
    "unknown_location": 422,
    "data_quality": 500,
}


def error_body(request: Request, code: str, message: str) -> dict:
    return {
        "error": {
            "code": code,
            "message": message,
            "request_id": getattr(request.state, "request_id", None),
        }
    }


def review_error_handler(request: Request, exc: ReviewError) -> JSONResponse:
    status = _STATUS_BY_CODE.get(exc.code, 500)
    return JSONResponse(status_code=status, content=error_body(request, exc.code, exc.message))


def validation_error_handler(request: Request, exc: RequestValidationError) -> JSONResponse:
    first = exc.errors()[0] if exc.errors() else {}
    location = ".".join(str(part) for part in first.get("loc", []))
    message = first.get("msg", "invalid input")
    detail = f"{location}: {message}" if location else message
    return JSONResponse(
        status_code=422, content=error_body(request, "invalid_input", detail)
    )


def internal_error_handler(request: Request, exc: Exception) -> JSONResponse:
    # Safe message only; the traceback with the request id goes to server logs.
    request_id = getattr(request.state, "request_id", None)
    print(f"[relay] unhandled error request_id={request_id!r} error={exc!r}", flush=True)
    return JSONResponse(
        status_code=500,
        content=error_body(request, "internal_error", "An internal error occurred."),
    )

"""API routes. Thin: validate, delegate to the service, translate errors."""

from __future__ import annotations

from fastapi import APIRouter, Depends, Query, Request

from app.api.deps import ReviewServiceDep
from app.api.dtos import AccountOut, OptionsOut, ReviewOut, account_out, options_out, review_out
from app.reviews.errors import InvalidWeek
from app.reviews.calendar import CalendarError, parse_week_start
from app.reviews.metrics import Metric

router = APIRouter(prefix="/api/v1")


@router.get("/accounts", response_model=list[AccountOut])
def list_accounts(service: ReviewServiceDep) -> list[AccountOut]:
    return [account_out(account) for account in service.list_accounts()]


@router.get("/accounts/{account_id}/review-options", response_model=OptionsOut)
def review_options(account_id: int, service: ReviewServiceDep) -> OptionsOut:
    return options_out(service.review_options(account_id))


@router.get("/accounts/{account_id}/weekly-review", response_model=ReviewOut)
def weekly_review(
    account_id: int,
    request: Request,
    service: ReviewServiceDep,
    week_start: str = Query(pattern=r"^\d{4}-\d{2}-\d{2}$", description="Monday, YYYY-MM-DD"),
    metric: Metric = Query(default=Metric.CALL_RECEIVED),
    location: str | None = Query(default=None, max_length=80),
) -> ReviewOut:
    try:
        week_monday = parse_week_start(week_start)
    except CalendarError as exc:
        raise InvalidWeek(str(exc)) from exc
    result = service.weekly_review(account_id, week_monday, metric, location)
    policy = service_settings(request).policy
    return review_out(
        result,
        request_id=request.state.request_id,
        policy_fields={
            "version": policy.version,
            "baseline_weeks": policy.baseline_weeks,
            "low_volume_reference": policy.low_volume_reference,
            "min_absolute_change": policy.min_absolute_change,
            "min_relative_change": policy.min_relative_change,
        },
    )


def service_settings(request: Request):
    return request.app.state.settings

"""Liveness and database-readiness checks. No configuration, no secrets."""

from __future__ import annotations

from fastapi import APIRouter, Request
from fastapi.responses import JSONResponse

from app.db.engine import ping

router = APIRouter()


@router.get("/healthz")
def liveness() -> dict[str, str]:
    return {"status": "ok"}


@router.get("/readyz")
def readiness(request: Request) -> JSONResponse:
    if ping(request.app.state.engine):
        return JSONResponse({"status": "ready"})
    return JSONResponse(status_code=503, content={"status": "storage_unavailable"})

