import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

// Dev server proxies /api to the local FastAPI process; both UI and API are
// served from one origin (http://127.0.0.1:5173) in development.
export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    strictPort: true,
    proxy: {
      "/api": "http://127.0.0.1:8000",
    },
  },
  test: {
    environment: "jsdom",
    globals: false,
  },
} as never);

// Typed API client. Types mirror the backend contract (backend/app/api/dtos.py);
// `npm run sync-openapi` regenerates src/features/review/openapi.json from the
// running API and the contract test verifies the two stay aligned.

export type Metric = "call_received" | "lead_created" | "appointment_set";

export type Reason =
  | "no_activity_recorded"
  | "insufficient_history"
  | "no_recent_activity"
  | "activity_after_zero_baseline"
  | "low_volume"
  | "below_recent_range"
  | "above_recent_range"
  | "no_review_flag";

export interface Account {
  id: number;
  name: string;
  industry: string;
  timezone: string;
}

export interface WeekPoint {
  week_start: string; // YYYY-MM-DD (Monday)
  covered: boolean;
  count: number;
}

export interface Comparison {
  count: number;
  reference: number | null;
  delta: number | null;
  percent_change: number | null;
  observed_min: number | null;
  observed_max: number | null;
  reason: Reason | null;
  classification_suppressed: boolean;
  weeks: WeekPoint[];
}

export interface LocationRow {
  location: string;
  first_observed_utc: string | null;
  view: Comparison;
}

export interface ReviewResponse {
  request_id: string;
  scope: {
    account_id: number;
    account_name: string;
    metric: Metric;
    location: string | null;
    week_start: string;
  };
  time: {
    timezone: string;
    week_start_local: string;
    week_end_local: string;
    week_start_utc: string;
    week_end_utc: string;
  };
  baseline: { week_count: number; weeks_covered: number; start_utc: string };
  policy: {
    version: string;
    baseline_weeks: number;
    low_volume_reference: number;
    min_absolute_change: number;
    min_relative_change: number;
  };
  coverage: {
    coverage_start_utc: string;
    coverage_end_utc: string;
    demo_now_utc: string;
    last_observed_event_utc: string | null;
    warnings: string[];
  };
  summary: Comparison;
  account_summary: Comparison;
  locations: LocationRow[];
}

export interface ReviewOptions {
  account: Account;
  timezone: string;
  locations: string[];
  default_week: string;
  available_weeks: string[];
  coverage: {
    coverage_start_utc: string;
    coverage_end_utc: string;
    demo_now_utc: string;
    last_observed_event_utc: string | null;
    warnings: string[];
  };
}

export class ApiError extends Error {
  constructor(
    readonly code: string,
    message: string,
    readonly requestId: string | null,
    readonly status: number,
  ) {
    super(message);
  }
}

async function request<T>(path: string, signal?: AbortSignal): Promise<T> {
  const response = await fetch(path, { signal, headers: { Accept: "application/json" } });
  if (!response.ok) {
    let code = "http_error";
    let message = `Request failed with status ${response.status}`;
    let requestId: string | null = response.headers.get("X-Request-ID");
    try {
      const body = await response.json();
      if (body?.error) {
        code = body.error.code ?? code;
        message = body.error.message ?? message;
        requestId = body.error.request_id ?? requestId;
      }
    } catch {
      // non-JSON error body; keep defaults
    }
    throw new ApiError(code, message, requestId, response.status);
  }
  return (await response.json()) as T;
}

export function fetchAccounts(signal?: AbortSignal): Promise<Account[]> {
  return request<Account[]>("/api/v1/accounts", signal);
}

export function fetchReviewOptions(
  accountId: number,
  signal?: AbortSignal,
): Promise<ReviewOptions> {
  return request<ReviewOptions>(
    `/api/v1/accounts/${accountId}/review-options`,
    signal,
  );
}

export interface ReviewQuery {
  accountId: number;
  weekStart: string;
  metric: Metric;
  location: string | null;
}

export function fetchWeeklyReview(
  query: ReviewQuery,
  signal?: AbortSignal,
): Promise<ReviewResponse> {
  const params = new URLSearchParams({
    week_start: query.weekStart,
    metric: query.metric,
  });
  if (query.location) params.set("location", query.location);
  return request<ReviewResponse>(
    `/api/v1/accounts/${query.accountId}/weekly-review?${params.toString()}`,
    signal,
  );
}

// URL search parameters are the canonical shareable filter state.
// Reload, back/forward, and shared links must reproduce the same view.

import type { Metric } from "./api";

export const METRICS: readonly Metric[] = [
  "call_received",
  "lead_created",
  "appointment_set",
];

export const DEFAULT_METRIC: Metric = "call_received";

export interface UrlFilters {
  account: number | null; // null => pick the first account
  week: string | null; // null => options default week
  metric: Metric;
  location: string; // "" => all locations
}

export function parseUrlFilters(
  search: string,
): { filters: UrlFilters; invalid: string[] } {
  const params = new URLSearchParams(search);
  const invalid: string[] = [];

  let account: number | null = null;
  const rawAccount = params.get("account");
  if (rawAccount !== null) {
    const parsed = Number.parseInt(rawAccount, 10);
    if (Number.isFinite(parsed) && parsed > 0 && String(parsed) === rawAccount) {
      account = parsed;
    } else {
      invalid.push(`account=${rawAccount}`);
    }
  }

  let week: string | null = null;
  const rawWeek = params.get("week");
  if (rawWeek !== null) {
    if (/^\d{4}-\d{2}-\d{2}$/.test(rawWeek) && new Date(rawWeek).getDay() === 1) {
      week = rawWeek;
    } else {
      invalid.push(`week=${rawWeek}`);
    }
  }

  let metric: Metric = DEFAULT_METRIC;
  const rawMetric = params.get("metric");
  if (rawMetric !== null) {
    if ((METRICS as readonly string[]).includes(rawMetric)) {
      metric = rawMetric as Metric;
    } else {
      invalid.push(`metric=${rawMetric}`);
    }
  }

  const location = params.get("location") ?? "";
  if (location.length > 80) {
    invalid.push("location");
  }

  return {
    filters: { account, week, metric, location: location.slice(0, 80) },
    invalid,
  };
}

export function filtersToSearch(filters: UrlFilters): string {
  const params = new URLSearchParams();
  if (filters.account !== null) params.set("account", String(filters.account));
  if (filters.week !== null) params.set("week", filters.week);
  if (filters.metric !== DEFAULT_METRIC) params.set("metric", filters.metric);
  if (filters.location) params.set("location", filters.location);
  const encoded = params.toString();
  return encoded ? `?${encoded}` : "";
}

// Display-only formatting. Comparisons stay unrounded end to end; rounding
// happens exactly here, at the edge.

const numberFormat = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const decimalFormat = new Intl.NumberFormat("en-US", {
  minimumFractionDigits: 1,
  maximumFractionDigits: 1,
});

export function formatCount(value: number | null | undefined): string {
  if (value === null || value === undefined) return "—";
  return numberFormat.format(value);
}

export function formatReference(value: number | null | undefined): string {
  if (value === null || value === undefined) return "—";
  return decimalFormat.format(value);
}

export function formatDelta(value: number | null | undefined): string {
  if (value === null || value === undefined) return "—";
  const rounded = decimalFormat.format(Math.abs(value));
  const sign = value > 0 ? "+" : value < 0 ? "−" : "";
  return `${sign}${rounded}`;
}

export function formatPercent(value: number | null | undefined): string {
  if (value === null || value === undefined) return "—";
  const rounded = decimalFormat.format(Math.abs(value));
  const sign = value > 0 ? "+" : value < 0 ? "−" : "";
  return `${sign}${rounded}%`;
}

export function formatRange(
  min: number | null | undefined,
  max: number | null | undefined,
): string {
  if (min === null || min === undefined || max === null || max === undefined) {
    return "—";
  }
  return `${numberFormat.format(min)}–${numberFormat.format(max)}`;
}

const weekLabel = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" });
const weekLabelWithYear = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
});

/** "Jul 20–26, 2026" for a week starting on the given Monday. */
export function formatWeekRange(mondayIso: string): string {
  const start = new Date(`${mondayIso}T00:00:00Z`);
  const end = new Date(start.getTime() + 6 * 24 * 3600 * 1000);
  const sameYear = start.getUTCFullYear() === end.getUTCFullYear();
  const startText = weekLabel.format(start);
  const endText = sameYear ? weekLabel.format(end) : weekLabelWithYear.format(end);
  return `${startText}–${endText}, ${start.getUTCFullYear()}`;
}

export function formatUtcTimestamp(iso: string | null | undefined): string {
  if (!iso) return "—";
  const moment = new Date(iso);
  return new Intl.DateTimeFormat("en-US", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "UTC",
  }).format(moment);
}

export const METRIC_LABELS: Record<string, string> = {
  call_received: "Calls received",
  lead_created: "Leads created",
  appointment_set: "Appointments set",
};

export const REASON_LABELS: Record<string, string> = {
  no_activity_recorded: "No activity recorded",
  insufficient_history: "Not enough history yet",
  no_recent_activity: "No activity this week",
  activity_after_zero_baseline: "Activity after weeks of none",
  low_volume: "Low volume",
  below_recent_range: "Below recent range",
  above_recent_range: "Above recent range",
  no_review_flag: "Within recent range",
};

// Data hook with stale-response protection: every parameter change aborts the
// in-flight request AND a sequence guard drops any late response, so a slow
// old request can never overwrite a newer filter selection.

import { useEffect, useRef, useState } from "react";
import {
  ApiError,
  fetchAccounts,
  fetchReviewOptions,
  fetchWeeklyReview,
  type Account,
  type ReviewOptions,
  type ReviewResponse,
} from "./api";
import type { Metric, ReviewQuery } from "./api";
import type { UrlFilters } from "./urlState";

interface ReviewState {
  accounts: Account[];
  accountsError: string | null;
  options: ReviewOptions | null;
  review: ReviewResponse | null;
  loading: boolean;
  error: { message: string; code: string } | null;
}

export function useReview(filters: UrlFilters): ReviewState & { reload: () => void } {
  const [state, setState] = useState<ReviewState>({
    accounts: [],
    accountsError: null,
    options: null,
    review: null,
    loading: true,
    error: null,
  });
  const [reloadCounter, setReloadCounter] = useState(0);
  const sequence = useRef(0);

  useEffect(() => {
    const currentSequence = ++sequence.current;
    const controller = new AbortController();
    const isCurrent = () => sequence.current === currentSequence;
    const apply = (patch: Partial<ReviewState>) => {
      if (isCurrent()) setState((previous) => ({ ...previous, ...patch }));
    };

    let cancelled = false;
    const onAbort = () => {
      cancelled = true;
    };
    controller.signal.addEventListener("abort", onAbort);

    (async () => {
      setState((previous) => ({ ...previous, loading: true, error: null }));
      try {
        const accounts = await fetchAccounts(controller.signal);
        if (cancelled || !isCurrent()) return;
        if (accounts.length === 0) {
          apply({ accounts, loading: false, review: null, options: null });
          return;
        }
        const account =
          filters.account && accounts.some((candidate) => candidate.id === filters.account)
            ? filters.account
            : accounts[0].id;
        const options = await fetchReviewOptions(account, controller.signal);
        if (cancelled || !isCurrent()) return;

        const week =
          filters.week && options.available_weeks.includes(filters.week)
            ? filters.week
            : options.default_week;
        const location =
          filters.location && options.locations.includes(filters.location)
            ? filters.location
            : "";

        const query: ReviewQuery = {
          accountId: account,
          weekStart: week,
          metric: filters.metric as Metric,
          location: location || null,
        };
        const review = await fetchWeeklyReview(query, controller.signal);
        if (cancelled || !isCurrent()) return;
        apply({ accounts, options, review, loading: false, error: null });
      } catch (error) {
        if (cancelled || !isCurrent() || controller.signal.aborted) return;
        if (error instanceof ApiError) {
          apply({ loading: false, error: { message: error.message, code: error.code } });
        } else {
          apply({
            loading: false,
            error: { message: "Could not reach the review service.", code: "network" },
          });
        }
      }
    })();

    return () => {
      controller.signal.removeEventListener("abort", onAbort);
      controller.abort();
    };
  }, [filters.account, filters.week, filters.metric, filters.location, reloadCounter]);

  return { ...state, reload: () => setReloadCounter((counter) => counter + 1) };
}

// Filter controls. All changes write to the URL; the server stays
// authoritative for validation and every derived number.

import type { Account, Metric, ReviewOptions } from "../api";
import { METRIC_LABELS, formatWeekRange } from "../format";
import { METRICS } from "../urlState";

interface ControlsProps {
  accounts: Account[];
  options: ReviewOptions | null;
  accountId: number | null;
  week: string;
  metric: Metric;
  location: string;
  onAccountChange: (id: number) => void;
  onWeekChange: (week: string) => void;
  onMetricChange: (metric: Metric) => void;
  onLocationChange: (location: string) => void;
}

const fieldStyle = { display: "flex", flexDirection: "column", gap: "0.25rem" } as const;

export function Controls({
  accounts,
  options,
  accountId,
  week,
  metric,
  location,
  onAccountChange,
  onWeekChange,
  onMetricChange,
  onLocationChange,
}: ControlsProps) {
  return (
    <form className="controls" onSubmit={(event) => event.preventDefault()}>
      <label style={fieldStyle}>
        Account
        <select
          value={accountId ?? ""}
          onChange={(event) => onAccountChange(Number(event.target.value))}
          disabled={accounts.length === 0}
        >
          {accounts.map((account) => (
            <option key={account.id} value={account.id}>
              {account.name}
            </option>
          ))}
        </select>
      </label>

      <label style={fieldStyle}>
        Week (complete weeks only)
        <select
          value={week}
          onChange={(event) => onWeekChange(event.target.value)}
          disabled={!options}
        >
          {options
            ? [...options.available_weeks].reverse().map((monday) => (
                <option key={monday} value={monday}>
                  {formatWeekRange(monday)}
                </option>
              ))
            : null}
        </select>
      </label>

      <fieldset className="metric-fieldset">
        <legend>Metric</legend>
        <div className="segmented" role="group" aria-label="Metric">
          {METRICS.map((candidate) => (
            <button
              key={candidate}
              type="button"
              aria-pressed={candidate === metric}
              className={candidate === metric ? "segment active" : "segment"}
              onClick={() => onMetricChange(candidate)}
            >
              {METRIC_LABELS[candidate]}
            </button>
          ))}
        </div>
      </fieldset>

      <label style={fieldStyle}>
        Location
        <select
          value={location}
          onChange={(event) => onLocationChange(event.target.value)}
          disabled={!options}
        >
          <option value="">All locations</option>
          {options
            ? options.locations.map((name) => (
                <option key={name} value={name}>
                  {name}
                </option>
              ))
            : null}
        </select>
      </label>
    </form>
  );
}

// Headline: this week vs the account's (or filtered location's) own recent
// history. Neutral language only — a change is a reason to look, not a
// verdict.

import type { Comparison, ReviewResponse } from "../api";
import {
  METRIC_LABELS,
  REASON_LABELS,
  formatCount,
  formatDelta,
  formatPercent,
  formatRange,
  formatReference,
  formatWeekRange,
} from "../format";

export function SummaryCard({ review }: { review: ReviewResponse }) {
  const summary: Comparison = review.summary;
  const filtered = review.scope.location !== null;
  const population = filtered ? ` — ${review.scope.location} only` : "";

  return (
    <section className="summary-card" aria-labelledby="summary-heading">
      <h2 id="summary-heading">
        {METRIC_LABELS[review.scope.metric] ?? review.scope.metric}
        <span className="summary-sub">
          {" "}
          · week of {formatWeekRange(review.scope.week_start)} · {review.time.timezone}
          {population}
        </span>
      </h2>

      <div className="summary-grid">
        <div className="summary-stat">
          <span className="stat-label">This week</span>
          <span className="stat-value">{formatCount(summary.count)}</span>
        </div>
        <div className="summary-stat">
          <span className="stat-label">8-week average</span>
          <span className="stat-value">{formatReference(summary.reference)}</span>
        </div>
        <div className="summary-stat">
          <span className="stat-label">Recent range</span>
          <span className="stat-value">
            {formatRange(summary.observed_min, summary.observed_max)}
          </span>
        </div>
        <div className="summary-stat">
          <span className="stat-label">Change vs average</span>
          <span className="stat-value">
            {formatDelta(summary.delta)} ({formatPercent(summary.percent_change)})
          </span>
        </div>
        <div className="summary-stat">
          <span className="stat-label">Status</span>
          <span
            className={
              summary.reason === "below_recent_range"
                ? "stat-value status-down"
                : summary.reason === "above_recent_range"
                  ? "stat-value status-up"
                  : "stat-value"
            }
          >
            {summaryLabel(summary)}
          </span>
        </div>
      </div>

      {review.coverage.warnings.includes("population_change") ? (
        <p className="warning" role="status">
          ⚠ New locations opened during the comparison window, so the overall
          classification is hidden. Totals still include every location.
        </p>
      ) : null}
      {summary.reason === "insufficient_history" ? (
        <p className="notice" role="status">
          Not enough recorded history for this week to form an 8-week baseline.
          Weekly counts are still shown.
        </p>
      ) : null}
    </section>
  );
}

function summaryLabel(summary: Comparison): string {
  if (summary.classification_suppressed) return "Classification hidden (population changed)";
  if (summary.reason === null) return "—";
  return REASON_LABELS[summary.reason] ?? summary.reason;
}

// Location comparison table: sortable within the bounded server response,
// with an expandable 9-week history per row. The browser never recomputes
// classifications — sorting and labels only.

import { useMemo, useState } from "react";
import type { LocationRow } from "../api";
import {
  REASON_LABELS,
  formatCount,
  formatDelta,
  formatPercent,
  formatRange,
  formatReference,
  formatWeekRange,
} from "../format";

type SortKey = "review" | "location" | "count" | "change";

interface LocationTableProps {
  rows: LocationRow[];
  weekStart: string;
}

export function LocationTable({ rows, weekStart }: LocationTableProps) {
  const [sortKey, setSortKey] = useState<SortKey>("review");
  const [expanded, setExpanded] = useState<string | null>(null);

  const sortedRows = useMemo(() => {
    if (sortKey === "review") return rows; // server ranking (flags first)
    const copy = [...rows];
    if (sortKey === "location") copy.sort((a, b) => a.location.localeCompare(b.location));
    if (sortKey === "count")
      copy.sort((a, b) => b.view.count - a.view.count || a.location.localeCompare(b.location));
    if (sortKey === "change")
      copy.sort(
        (a, b) =>
          (b.view.delta ?? -Infinity) - (a.view.delta ?? -Infinity) ||
          a.location.localeCompare(b.location),
      );
    return copy;
  }, [rows, sortKey]);

  const header = (key: SortKey, label: string, alignClass = "num") => {
    const isSorted = sortKey === key;
    return (
      <th
        scope="col"
        aria-sort={isSorted ? "ascending" : "none"}
        className={alignClass}
      >
        {key === "review" ? (
          label
        ) : (
          <button type="button" className="sort-button" onClick={() => setSortKey(key)}>
            {label}
            <span aria-hidden="true">{isSorted ? " ▲" : " ↕"}</span>
          </button>
        )}
      </th>
    );
  };

  return (
    <table className="location-table">
      <caption>
        Location comparison · week of {formatWeekRange(weekStart)} · flags are ranked:
        decreases by shortfall, then increases, then other states
      </caption>
      <thead>
        <tr>
          {header("location", "Location", "text")}
          {header("count", "This week")}
          <th scope="col" className="num">8-week average</th>
          <th scope="col" className="num">Recent range</th>
          {header("change", "Change")}
          <th scope="col" className="text">Status</th>
          <th scope="col" className="sr-only">History</th>
        </tr>
      </thead>
      <tbody>
        {sortedRows.map((row) => (
          <>
            <tr key={row.location}>
              <th scope="row" className="text">
                {row.location}
              </th>
              <td className="num">{formatCount(row.view.count)}</td>
              <td className="num">{formatReference(row.view.reference)}</td>
              <td className="num">
                {formatRange(row.view.observed_min, row.view.observed_max)}
              </td>
              <td className="num">
                {formatDelta(row.view.delta)}{" "}
                <span className="percent">
                  ({formatPercent(row.view.percent_change)})
                </span>
              </td>
              <td className="text">
                <span
                  className={
                    row.view.reason === "below_recent_range"
                      ? "status status-down"
                      : row.view.reason === "above_recent_range"
                        ? "status status-up"
                        : "status"
                  }
                >
                  {row.view.reason ? (REASON_LABELS[row.view.reason] ?? row.view.reason) : "—"}
                </span>
              </td>
              <td className="num">
                <button
                  type="button"
                  className="expand-button"
                  aria-expanded={expanded === row.location}
                  aria-controls={`history-${cssSafe(row.location)}`}
                  onClick={() =>
                    setExpanded((current) => (current === row.location ? null : row.location))
                  }
                >
                  {expanded === row.location ? "Hide history" : "Show history"}
                </button>
              </td>
            </tr>
            {expanded === row.location ? (
              <tr className="history-row" id={`history-${cssSafe(row.location)}`}>
                <td colSpan={7}>
                  <WeekHistory row={row} />
                </td>
              </tr>
            ) : null}
          </>
        ))}
      </tbody>
    </table>
  );
}

function WeekHistory({ row }: { row: LocationRow }) {
  const weeks = row.view.weeks;
  const max = Math.max(1, ...weeks.map((point) => point.count));
  const firstObserved = row.first_observed_utc
    ? new Date(row.first_observed_utc).toISOString().slice(0, 10)
    : null;
  return (
    <div className="week-history">
      <ol>
        {weeks.map((point) => (
          <li
            key={point.week_start}
            className={point.covered ? "covered" : "uncovered"}
          >
            <span className="week-label">{formatWeekRange(point.week_start)}</span>
            <span
              className="week-bar"
              aria-hidden="true"
              style={{ width: `${Math.round((point.count / max) * 100)}%` }}
            />
            <span className="week-count">{formatCount(point.count)}</span>
          </li>
        ))}
      </ol>
      <p className="history-note">
        {firstObserved
          ? `First recorded activity: ${firstObserved} (not an opening date). `
          : "No recorded activity in this window. "}
        Grey weeks fall outside the assumed fixture recording interval and are
        not used in the average.
      </p>
    </div>
  );
}

function cssSafe(name: string): string {
  return name.replace(/[^a-zA-Z0-9_-]/g, "_");
}

// Explicit loading / error / empty states.

export function LoadingState({ label }: { label: string }) {
  return (
    <div className="state-box" role="status" aria-busy="true">
      <span className="spinner" aria-hidden="true" />
      {label}
    </div>
  );
}

export function ErrorState({
  message,
  onRetry,
}: {
  message: string;
  onRetry: () => void;
}) {
  return (
    <div className="state-box error" role="alert">
      <p>{message}</p>
      <button type="button" onClick={onRetry}>
        Try again
      </button>
    </div>
  );
}

export function EmptyState({ message }: { message: string }) {
  return (
    <div className="state-box" role="status">
      {message}
    </div>
  );
}

// Application shell: URL is the canonical filter state (reload / back /
// forward / sharing reproduce the same view); the server is authoritative
// for every calculation.

import { useCallback, useEffect, useMemo, useState } from "react";
import { Controls } from "./features/review/components/Controls";
import { LocationTable } from "./features/review/components/LocationTable";
import { SummaryCard } from "./features/review/components/SummaryCard";
import { EmptyState, ErrorState, LoadingState } from "./features/review/components/States";
import type { Metric } from "./features/review/api";
import { formatUtcTimestamp } from "./features/review/format";
import { useReview } from "./features/review/useReview";
import { filtersToSearch, parseUrlFilters, type UrlFilters } from "./features/review/urlState";

export default function App() {
  const [filters, setFilters] = useState<UrlFilters>(() => {
    const { filters: parsed } = parseUrlFilters(window.location.search);
    return parsed;
  });
  const [urlNotice, setUrlNotice] = useState<string | null>(null);

  const pushFilters = useCallback((next: UrlFilters, replace = false) => {
    setFilters(next);
    const search = filtersToSearch(next);
    if (replace) {
      window.history.replaceState(null, "", search || window.location.pathname);
    } else {
      window.history.pushState(null, "", search || window.location.pathname);
    }
  }, []);

  // Back/forward reproduce earlier views.
  useEffect(() => {
    const onPopState = () => {
      const { filters: parsed, invalid } = parseUrlFilters(window.location.search);
      setFilters(parsed);
      setUrlNotice(
        invalid.length > 0
          ? `Some URL parameters were invalid and reset to defaults: ${invalid.join(", ")}`
          : null,
      );
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  const { accounts, options, review, loading, error, reload } = useReview(filters);

  // When the loaded data disagrees with the URL (unknown account/week/location),
  // recover to valid values and surface a clear notice.
  useEffect(() => {
    if (!options || loading || error) return;
    const patches: Partial<UrlFilters> = {};
    if (filters.account !== null && filters.account !== options.account.id) {
      patches.account = options.account.id;
    }
    if (filters.week !== null && filters.week !== review?.scope.week_start) {
      patches.week = review?.scope.week_start ?? null;
    }
    if (
      filters.location &&
      !options.locations.includes(filters.location)
    ) {
      patches.location = "";
    }
    if (Object.keys(patches).length > 0) {
      setFilters((current) => ({ ...current, ...patches }));
      setUrlNotice("Some filters in the URL were not valid for this account and were reset.");
    }
  }, [options, review, loading, error, filters]);

  const currentAccount = useMemo(
    () => accounts.find((account) => account.id === (filters.account ?? options?.account.id)),
    [accounts, filters.account, options],
  );

  const onAccountChange = (id: number) => {
    // Locations belong to an account; switching clears an incompatible filter.
    pushFilters({ ...filters, account: id, location: "" });
  };
  const onWeekChange = (week: string) => pushFilters({ ...filters, week });
  const onMetricChange = (metric: Metric) => pushFilters({ ...filters, metric });
  const onLocationChange = (location: string) => pushFilters({ ...filters, location });

  return (
    <div className="app">
      <a className="skip-link" href="#main">
        Skip to content
      </a>
      <header className="app-header">
        <h1>Relay · Weekly activity review</h1>
        <p className="demo-clock">
          Fixture demo date: {formatUtcTimestamp(review?.coverage.demo_now_utc ?? options?.coverage.demo_now_utc)}
          {review?.coverage.last_observed_event_utc
            ? ` · last recorded event ${formatUtcTimestamp(review.coverage.last_observed_event_utc)}`
            : null}
        </p>
      </header>

      <main id="main">
        <Controls
          accounts={accounts}
          options={options}
          accountId={currentAccount?.id ?? filters.account}
          week={review?.scope.week_start ?? filters.week ?? ""}
          metric={filters.metric}
          location={filters.location}
          onAccountChange={onAccountChange}
          onWeekChange={onWeekChange}
          onMetricChange={onMetricChange}
          onLocationChange={onLocationChange}
        />

        {urlNotice ? (
          <p className="notice" role="status">
            {urlNotice}
          </p>
        ) : null}

        {error ? (
          <ErrorState message={error.message} onRetry={reload} />
        ) : loading ? (
          <LoadingState label="Loading weekly review…" />
        ) : !review ? (
          <EmptyState message="No accounts are available to this principal." />
        ) : review.summary.reason === "no_activity_recorded" &&
          review.locations.length === 0 ? (
          <EmptyState
            message={`No activity has been recorded for ${review.scope.account_name} as of this week.`}
          />
        ) : (
          <>
            <SummaryCard review={review} />
            <LocationTable rows={review.locations} weekStart={review.scope.week_start} />
            <footer className="footnotes">
              <p>
                “8-week average” is the mean of the eight preceding complete weeks
                (this week excluded). Change thresholds: flagged only when the move
                beyond the recent range is ≥{review.policy.min_absolute_change} events
                and ≥{Math.round(review.policy.min_relative_change * 100)}% of the
                range edge — policy {review.policy.version}. “Within recent range”
                means those explicit thresholds were not met; it is not a judgement
                of business health.
              </p>
              <p>
                Weeks shown in grey fall outside the assumed fixture recording
                interval ({formatUtcTimestamp(review.coverage.coverage_start_utc)} to{" "}
                {formatUtcTimestamp(review.coverage.coverage_end_utc)}) and are never
                averaged in. All boundaries are local Mondays in{" "}
                {review.time.timezone}. Request {review.request_id}.
              </p>
            </footer>
          </>
        )}
      </main>
    </div>
  );
}

