        const target = new URL(url, "http://localhost");
        if (target.pathname.endsWith("/accounts")) return jsonResponse(accountsBody);
        if (target.pathname.endsWith("/review-options")) return jsonResponse(optionsBody(1));
        // weekly-review: first call slow (old week), second call fast (new week)
        weekFetch += 1;
        const week = target.searchParams.get("week_start");
        if (weekFetch === 1) {
          await new Promise((resolve) => setTimeout(resolve, 150));
          return jsonResponse(reviewBody("2026-07-13"));
        }
        return jsonResponse(reviewBody(week ?? ""));
      }),
    );

    const { result, rerender } = renderHook(({ week }) => useReview({ account: 1, week, metric: "call_received" as const, location: "" }), {
      initialProps: { week: "2026-07-13" },
    });

    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.review?.scope.week_start).toBe("2026-07-13");

    // Switch to the newer week; its response arrives BEFORE the old one.
    rerender({ week: "2026-07-20" });
    await waitFor(() => expect(result.current.review?.scope.week_start).toBe("2026-07-20"));

    // The slow old response lands now and must be dropped.
    await new Promise((resolve) => setTimeout(resolve, 250));
    expect(result.current.review?.scope.week_start).toBe("2026-07-20");
    expect(result.current.error).toBeNull();
  });

  it("surfaces ApiError messages with a retry path", async () => {
    let attempts = 0;
    vi.stubGlobal(
      "fetch",
      vi.fn(async (url: string) => {
        if (url.includes("/accounts") || url.includes("/review-options")) {
          attempts += 0;
          const target = new URL(url, "http://localhost");
          return jsonResponse(
            target.pathname.endsWith("/accounts") ? accountsBody : optionsBody(1),
          );
        }
        attempts += 1;
        if (attempts === 1) {
          return jsonResponse({ error: { code: "internal_error", message: "An internal error occurred.", request_id: "x" } }, 500);
        }
        return jsonResponse(reviewBody("2026-07-20"));
      }),
    );

    const { result } = renderHook(() =>
      useReview({ account: 1, week: "2026-07-20", metric: "call_received" as const, location: "" }),
    );
    await waitFor(() => expect(result.current.error?.code).toBe("internal_error"));
    expect(result.current.review).toBeNull();

    act(() => result.current.reload());
    await waitFor(() => expect(result.current.review?.scope.week_start).toBe("2026-07-20"));
    expect(result.current.error).toBeNull();
  });
});

// Contract guard: the committed OpenAPI schema (generated by
// `npm run sync-openapi`) must expose every field the typed client reads.
import { describe, expect, it } from "vitest";
import schema from "../src/features/review/openapi.json";

const schemas = (schema as { components: { schemas: Record<string, { properties: Record<string, unknown> }> } })
  .components.schemas;

function properties(name: string): string[] {
  return Object.keys(schemas[name]?.properties ?? {});
}

describe("backend contract matches typed client", () => {
  it("exposes the three review endpoints", () => {
    const paths = Object.keys((schema as { paths: Record<string, unknown> }).paths);
    expect(paths).toContain("/api/v1/accounts");
    expect(paths).toContain("/api/v1/accounts/{account_id}/review-options");
    expect(paths).toContain("/api/v1/accounts/{account_id}/weekly-review");
  });

  it("ReviewOut carries every client-read field, with nullable comparisons", () => {
    const fields = properties("ReviewOut");
    for (const field of [
      "request_id",
      "scope",
      "time",
      "baseline",
      "policy",
      "coverage",
      "summary",
      "account_summary",
      "locations",
    ]) {
      expect(fields).toContain(field);
    }
  });

  it("Comparison exposes nullable reference/delta/percent with a reason", () => {
    const fields = properties("ComparisonOut");
    for (const field of [
      "count",
      "reference",
      "delta",
      "percent_change",
      "observed_min",
      "observed_max",
      "reason",
      "classification_suppressed",
      "weeks",
    ]) {
      expect(fields).toContain(field);
    }
    const reason = schemas.ComparisonOut.properties.reason as { type?: string; anyOf?: unknown[] };
    expect(reason.anyOf ?? reason.type).toBeTruthy(); // nullable in the contract
  });

  it("metric enum values match the client's Metric type", () => {
    const metricParam = (
      schema as {
        paths: Record<string, { get?: { parameters?: Array<{ name: string; schema?: { enum?: string[] } }> } }>;
      }
    ).paths["/api/v1/accounts/{account_id}/weekly-review"].get?.parameters ?? [];
    const metric = metricParam.find((parameter) => parameter.name === "metric");
    expect(metric?.schema?.enum).toEqual([
      "call_received",
      "lead_created",
      "appointment_set",
    ]);
  });
});

